SELECT

FROM RwaInstSpvProduct a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instSpvPromoterId = #{instSpvPromoterId}


    AND a.instSpvCompanyId = #{instSpvCompanyId}


    AND a.productNo LIKE CONCAT('%',#{productNo}, '%')


    AND a.tokenName LIKE CONCAT('%',#{tokenName}, '%')


    AND a.tokenLogo LIKE CONCAT('%',#{tokenLogo}, '%')


    AND a.tokenIssueNumber = #{tokenIssueNumber}


    AND a.raiseCurrency LIKE CONCAT('%',#{raiseCurrency}, '%')


    AND a.raiseAmount = #{raiseAmount}


    AND a.assetEndValuation = #{assetEndValuation}


    AND a.issueDays = #{issueDays}


    AND a.purchaseStartDate = #{purchaseStartDate}


    AND a.purchaseEndDate = #{purchaseEndDate}


    AND a.operationStarDate = #{operationStarDate}


    AND a.operationEndDate = #{operationEndDate}


    AND a.raiseEstablishedRatio = #{raiseEstablishedRatio}


    AND a.companyAssetName LIKE CONCAT('%',#{companyAssetName}, '%')


    AND a.companyAssetDesc LIKE CONCAT('%',#{companyAssetDesc}, '%')


    AND a.companyRaiseUse LIKE CONCAT('%',#{companyRaiseUse}, '%')


    AND a.dividendRatio = #{dividendRatio}


    AND a.dividendFrequency LIKE CONCAT('%',#{dividendFrequency}, '%')


    AND a.dividendFreezeDays = #{dividendFreezeDays}


    AND a.raiseMarginRatio = #{raiseMarginRatio}


    AND a.raiseMarginState = #{raiseMarginState}


    AND a.purchasedSumAmount = #{purchasedSumAmount}


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}


    AND a.checkBy LIKE CONCAT('%',#{checkBy}, '%')


    AND a.checkTime = #{checkTime}
